-- MIG-21 (parte 1): documento, evidência, selo e objeto. A evidência usa o vetor caso-01 do atta-core (bytes do JCS,
-- sha256 e Código ATTA congelados), então os CHECKs são provados contra o algoritmo. Só dados fictícios; rollback.
begin;
create extension if not exists pgtap with schema extensions;
select plan(40);

insert into platform.tenant (id, name) values ('aaaaaaaa-0000-4000-8000-000000000001', 'Clínica Alfa Ficticia');
insert into platform.tenant (id, name) values ('bbbbbbbb-0000-4000-8000-000000000002', 'Clínica Beta Ficticia');
insert into network.person (id, full_name, is_incomplete) values ('cccccccc-0000-4000-8000-0000000000c1', 'Paciente Ficticio', true),
  ('cccccccc-0000-4000-8000-0000000000c2', 'Paciente Da Outra', true);
insert into network.person_tenant_link (tenant_id, person_id) values ('aaaaaaaa-0000-4000-8000-000000000001', 'cccccccc-0000-4000-8000-0000000000c1'),
  ('bbbbbbbb-0000-4000-8000-000000000002', 'cccccccc-0000-4000-8000-0000000000c2');
insert into documents.template (id, tenant_id, kind, title, frequency, required, draft_body, status, current_version)
  values ('dddddddd-0000-4000-8000-0000000000d1', 'aaaaaaaa-0000-4000-8000-000000000001', 'tcle', 'TCLE Ficticio',
          'por_procedimento', true, 'Texto fictício.', 'rascunho', null);
insert into documents.template_version (id, tenant_id, template_id, version, kind, title, frequency, required, body, body_sha256, published_by)
  values ('dddddddd-0000-4000-8000-0000000000e1', 'aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000d1',
          1, 'tcle', 'TCLE Ficticio', 'por_procedimento', true, 'Texto fictício.',
          encode(sha256(convert_to('Texto fictício.', 'UTF8')), 'hex'), 'cccccccc-0000-4000-8000-0000000000c1');
insert into documents.template (id, tenant_id, kind, title, frequency, required, draft_body) values
  ('dddddddd-0000-4000-8000-0000000000d2', 'bbbbbbbb-0000-4000-8000-000000000002', 'tcle', 'TCLE Beta', 'por_procedimento', true, 'Beta.');
insert into documents.template_version (id, tenant_id, template_id, version, kind, title, frequency, required, body, body_sha256, published_by)
  values ('dddddddd-0000-4000-8000-0000000000e2', 'bbbbbbbb-0000-4000-8000-000000000002', 'dddddddd-0000-4000-8000-0000000000d2',
          1, 'tcle', 'TCLE Beta', 'por_procedimento', true, 'Beta.', encode(sha256(convert_to('Beta.', 'UTF8')), 'hex'),
          'cccccccc-0000-4000-8000-0000000000c2');

-- ---------------------------------------------------------------- documento: dono e divisória
select lives_ok($$ insert into documents.document (id, tenant_id, template_version_id, person_id, folder_section)
  values ('eeeeeeee-0000-4000-8000-0000000000e1', 'aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e1',
          'cccccccc-0000-4000-8000-0000000000c1', 'termos') $$, 'termo do paciente, na divisória Termos');
select throws_ok($$ insert into documents.document (tenant_id, template_version_id, folder_section)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e1', 'termos') $$, '23514', null, 'documento sem dono é recusado');
select throws_ok($$ insert into documents.document (tenant_id, template_version_id, person_id)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e1', 'cccccccc-0000-4000-8000-0000000000c1') $$, '23514', null, 'documento de paciente sem divisória é recusado');
select throws_ok($$ insert into documents.document (tenant_id, person_id, folder_section)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'cccccccc-0000-4000-8000-0000000000c1', 'termos') $$, '23514', null, 'termo sem versão de modelo é recusado');
select lives_ok($$ insert into documents.document (tenant_id, person_id, folder_section)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'cccccccc-0000-4000-8000-0000000000c1', 'docs_clinicos') $$, 'doc clínico enviado não precisa de modelo');
-- isolamento entre clínicas (FKs compostas)
select throws_ok($$ insert into documents.document (tenant_id, template_version_id, person_id, folder_section)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e1', 'cccccccc-0000-4000-8000-0000000000c2', 'termos') $$, '23503', null, 'paciente não vinculado a esta clínica é recusado');
select throws_ok($$ insert into documents.document (tenant_id, template_version_id, person_id, folder_section)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e2', 'cccccccc-0000-4000-8000-0000000000c1', 'termos') $$, '23503', null, 'versão de modelo de outra clínica é recusada');
select throws_ok($$ insert into documents.document (tenant_id, template_version_id, professional_link_id)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'dddddddd-0000-4000-8000-0000000000e1', gen_random_uuid()) $$, '23503', null, 'vínculo de profissional que não é desta clínica é recusado');

-- ---------------------------------------------------------------- ciclo de vida (§17.6, §10.2.3)
select throws_ok($$ update documents.document set status = 'assinado_definitivo' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'aguardando não pula para definitivo');
select throws_ok($$ update documents.document set status = 'cancelado' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, '23514', null, 'cancelar sem motivo é recusado');
select throws_ok($$ update documents.document set status = 'cancelado', cancel_reason = 'outro', cancelled_at = now() where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, '23514', null, 'motivo fora dos 6 do PDD é recusado');
select lives_ok($$ update documents.document set status = 'pre_assinado' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'aguardando → pré-assinado');
select throws_ok($$ update documents.document set person_id = null, professional_link_id = null where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, null, null, 'dono do documento não se troca');
select throws_ok($$ update documents.document set status = 'substituido', replaced_by_document_id = (select id from documents.document where folder_section = 'docs_clinicos') where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'pré-assinado não vira substituído (§17.6)');
select lives_ok($$ update documents.document set status = 'assinado_definitivo' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'pré-assinado → definitivo');
select throws_ok($$ update documents.document set folder_section = 'docs_clinicos' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'divisória não se troca');
select throws_ok($$ update documents.document set status = 'cancelado', cancel_reason = 'no_show', cancelled_at = now() where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'definitivo é final');
select throws_ok($$ delete from documents.document where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'documento não se apaga');
-- substituição: não aponta para si mesmo; o substituto não muda depois
select throws_ok($$ update documents.document set status = 'substituido', replaced_by_document_id = 'eeeeeeee-0000-4000-8000-0000000000e1' where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, '23514', null, 'documento não substitui a si mesmo');
select lives_ok($$ update documents.document set status = 'substituido', replaced_by_document_id = (select id from documents.document where folder_section = 'docs_clinicos') where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'definitivo → substituído com o documento novo');
select throws_ok($$ update documents.document set replaced_by_document_id = (select id from documents.document where folder_section = 'termos' and status = 'aguardando_assinatura' limit 1) where id = 'eeeeeeee-0000-4000-8000-0000000000e1' $$, 'P0001', 'ATTA-IN-0002', 'o substituto não muda depois');

-- ---------------------------------------------------------------- evidência (vetor caso-01)
select lives_ok($$ insert into documents.evidence (tenant_id, document_id, atta_sign_version, payload_canonical, evidence_sha256, atta_code, signed_at)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'eeeeeeee-0000-4000-8000-0000000000e1', '1', decode('', 'hex'),
          '95d0d4842a89fbc60bfac2d3e5a8fe3a9c592f69f392debf9c506187087ae3e8', 'ATTA-JQ8D-911A-H7XW', '2026-11-23T14:05:09.412Z') $$,
  'evidência do caso-01: bytes do JCS, sha256 e Código ATTA do vetor');
select throws_ok($$ insert into documents.evidence (tenant_id, document_id, atta_sign_version, payload_canonical, evidence_sha256, atta_code, signed_at)
  values ('aaaaaaaa-0000-4000-8000-000000000001', 'eeeeeeee-0000-4000-8000-0000000000e1', '1', decode('', 'hex'),
          repeat('0', 64), 'ATTA-0000-0000-0000', '2026-11-23T14:05:09.412Z') $$, '23514', null, 'sha256 que não é o dos bytes é recusado');
select throws_ok($$ insert into documents.evidence (tenant_id, document_id, atta_sign_version, payload_canonical, evidence_sha256, atta_code, signed_at)
  values ('aaaaaaaa-0000-4000-8000-000000000001', (select id from documents.document where folder_section = 'docs_clinicos'), '1', decode('', 'hex'),
          '95d0d4842a89fbc60bfac2d3e5a8fe3a9c592f69f392debf9c506187087ae3e8', 'ATTA-AAAA-BBBB-CCCC', '2026-11-23T14:05:09.413Z') $$, '23514', null, 'signed_at diferente do signature.signed_at do próprio payload é recusado');
select throws_ok($$ insert into documents.evidence (tenant_id, document_id, atta_sign_version, payload_canonical, evidence_sha256, atta_code, signed_at)
  values ('aaaaaaaa-0000-4000-8000-000000000001', (select id from documents.document where folder_section = 'docs_clinicos'), '1', decode('', 'hex'),
          '95d0d4842a89fbc60bfac2d3e5a8fe3a9c592f69f392debf9c506187087ae3e8', 'ATTA-IIII-LLLL-OOOO', '2026-11-23T14:05:09.412Z') $$, '23514', null, 'Código ATTA fora do alfabeto Crockford é recusado');
select throws_ok($$ insert into documents.evidence (tenant_id, document_id, atta_sign_version, payload_canonical, evidence_sha256, atta_code, signed_at)
  values ('aaaaaaaa-0000-4000-8000-000000000001', (select id from documents.document where folder_section = 'docs_clinicos'), '1', decode('', 'hex'),
          '95d0d4842a89fbc60bfac2d3e5a8fe3a9c592f69f392debf9c506187087ae3e8', 'ATTA-AAAA-BBBB-CCCD', '2026-11-23T14:05:09.412345Z') $$, '23514', null, 'signed_at com microssegundos é recusado (só ms)');
select throws_ok($$ update documents.evidence set code_nonce = 1 $$, 'P0001', 'ATTA-IN-0002', 'evidência não se altera');
select throws_ok($$ delete from documents.evidence $$, 'P0001', 'ATTA-IN-0002', 'evidência não se apaga');
select throws_ok($$ truncate documents.evidence cascade $$, 'P0001', 'ATTA-IN-0002', 'evidência não se trunca');

-- ---------------------------------------------------------------- selo e manifesto
select throws_ok($$ insert into documents.seal_key (kid, public_key_spki, valid_from, valid_until) values ('seal-teste', decode(repeat('00', 44), 'hex'), now(), now() - interval '1 day') $$, '23514', null, 'janela da chave invertida é recusada');
insert into documents.seal_key (kid, public_key_spki, valid_from) values ('staging-seal-teste', decode(repeat('00', 44), 'hex'), now());
select throws_ok($$ insert into documents.seal (tenant_id, evidence_id, kid, signature) values ('aaaaaaaa-0000-4000-8000-000000000001', (select id from documents.evidence), 'staging-seal-teste', decode(repeat('00', 63), 'hex')) $$, '23514', null, 'assinatura que não tem 64 bytes é recusada');
select throws_ok($$ insert into documents.seal (tenant_id, evidence_id, kid, signature) values ('bbbbbbbb-0000-4000-8000-000000000002', (select id from documents.evidence), 'staging-seal-teste', decode(repeat('00', 64), 'hex')) $$, '23503', null, 'selo com clínica diferente da evidência é recusado');
select throws_ok($$ update documents.seal_key set valid_until = now() - interval '1 day' $$, 'P0001', 'ATTA-IN-0002', 'aposentar no passado é recusado');
select throws_ok($$ update documents.seal_key set public_key_spki = decode(repeat('11', 44), 'hex') $$, 'P0001', 'ATTA-IN-0002', 'a chave pública não muda');
select lives_ok($$ update documents.seal_key set valid_until = now() + interval '1 hour' $$, 'aposentar a chave (valid_until de nulo para depois) é aceito');
select throws_ok($$ update documents.seal_key set valid_until = now() + interval '2 hours' $$, 'P0001', 'ATTA-IN-0002', 'aposentar de novo é recusado');
select throws_ok($$ delete from documents.seal_key $$, 'P0001', 'ATTA-IN-0002', 'chave do manifesto não se apaga');

-- ---------------------------------------------------------------- RLS e grants
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in
  ('documents.document'::regclass, 'documents.evidence'::regclass, 'documents.seal'::regclass, 'documents.seal_key'::regclass,
   'documents.seal_timestamp'::regclass, 'documents.stored_object'::regclass)), 'as 6 tabelas com RLS forçada');
select ok(not has_table_privilege('authenticated', 'documents.evidence', 'SELECT') and not has_table_privilege('anon', 'documents.evidence', 'SELECT')
  and not has_table_privilege('authenticated', 'documents.stored_object', 'SELECT') and not has_table_privilege('service_role', 'documents.evidence', 'INSERT'),
  'evidência e objeto sem grant: só por função');
select ok(not has_table_privilege('authenticated', 'documents.document', 'INSERT') and not has_table_privilege('authenticated', 'documents.document', 'UPDATE'),
  'o painel não escreve documento pela tabela');

select * from finish();
rollback;
